// Checks the TypeScript port against what the ORIGINAL Python code decides for the same snapshot.
// The reference is generated by scripts/gen-python-reference.py (it runs the real functions of pages/home.py).
import { describe, expect, it } from "vitest";
import ref from "./__fixtures__/python-reference.json";
import {
  computeMarkerStates, groupActiveAlerts, jmaIssued, matches, officialAlert, officialLine, prepareAlerts, vaaStatus,
} from "./alertLogic";
import { timeLabel, timeShort } from "./format";
import type { AlertEvent, AlertPayload } from "./types";
import { MAPPABLE_VOLCANOES, VolcanoIndex } from "./volcanoes";

type Expected = {
  size: number; fill: string; stroke: string; width: number; opacity: number;
  bubble: { kind: string; timeLine: string } | null;
  extra?: { officialLine: string; jmaIssued: string | null; vaaCurrent: number; mirovaTime: string | null };
};
const DEFAULT: Expected = { size: 8, fill: "transparent", stroke: "#ffffff", width: 2.4, opacity: 0.5, bubble: null };

const payload = ref.payload as unknown as AlertPayload;
const prepared = prepareAlerts(payload, Date.parse(ref.now));
const expected = ref.expected as unknown as Record<string, Expected>;
const states = computeMarkerStates(prepared, MAPPABLE_VOLCANOES);

describe("marker decisions match the Python app (snapshot " + ref.now + ")", () => {
  it("covers every mappable volcano", () => {
    expect(states.length).toBe(MAPPABLE_VOLCANOES.length);
  });

  it("size / fill / border / opacity / bubble are identical for all volcanoes", () => {
    const diffs: string[] = [];
    for (const s of states) {
      const want = expected[String(s.volcano.n)] ?? DEFAULT;
      const got = { size: s.size, fill: s.fill, stroke: s.stroke, width: s.width, opacity: s.opacity, bubble: s.bubble };
      if (JSON.stringify(got) !== JSON.stringify({ ...want, extra: undefined })) {
        diffs.push(`${s.volcano.n} ${s.volcano.name}: got ${JSON.stringify(got)} want ${JSON.stringify(want)}`);
      }
    }
    expect(diffs).toEqual([]);
  });

  it("has the bubbles the snapshot should show", () => {
    const bubbles = states.filter((s) => s.bubble).map((s) => s.name).sort();
    expect(bubbles.length).toBe(Object.values(expected).filter((e) => e.bubble).length);
    expect(bubbles).toContain("Sakurajima"); // Tokyo VAAC calls it "SAKURAJIMA [AIRA CALDERA]"
  });

  it("status lines (official level, JMA issue time, current advisories) are identical", () => {
    const diffs: string[] = [];
    for (const s of states) {
      const want = expected[String(s.volcano.n)]?.extra;
      if (!want) continue;
      const official = officialAlert(payload, s.volcano.name, s.volcano.n);
      const got = {
        officialLine: officialLine(official),
        vaaCurrent: vaaStatus(prepared, s.volcano.name).current.length,
      };
      if (got.officialLine !== want.officialLine) diffs.push(`${s.name}: official "${got.officialLine}" != "${want.officialLine}"`);
      if (got.vaaCurrent !== want.vaaCurrent) diffs.push(`${s.name}: vaa ${got.vaaCurrent} != ${want.vaaCurrent}`);
      if (want.jmaIssued !== null && jmaIssued(prepared, s.volcano.name) !== want.jmaIssued) {
        diffs.push(`${s.name}: jma issued "${jmaIssued(prepared, s.volcano.name)}" != "${want.jmaIssued}"`);
      }
    }
    expect(diffs).toEqual([]);
  });
});

describe("time labels", () => {
  it.each(ref.timeCases)("%j", (c) => {
    expect(timeLabel(c.raw)).toBe(c.label);
    expect(timeShort(c.raw)).toBe(c.short);
  });
});

describe("name matching", () => {
  it("accepts the spellings the sources use for Sakurajima", () => {
    for (const candidate of ["Sakurajima", "SAKURAJIMA [AIRA CALDERA]", "Aira", "Sakurajima (Aira Caldera)", "SAKURAJIMA 282080"]) {
      expect(matches("Aira", candidate)).toBe(true);
    }
    expect(matches("Aira", "Asosan")).toBe(false);
  });
  it("maps JMA names through JMA_NAME_MAP", () => {
    expect(matches("Kirishimayama", "Kirishimayama(Shinmoedake)")).toBe(true);
    expect(matches("Akan", "Meakandake")).toBe(true);
  });
});

describe("VolcanoIndex", () => {
  const index = new VolcanoIndex();
  it("resolves by number, by alias and by name+country", () => {
    expect(index.resolve({ volcano_number: "282080" })).toBe(282080);
    expect(index.resolve({ name: "Sakurajima (Aira Caldera)" })).toBe(282080);
    expect(index.resolve({ name: "Sheveluch" })).toBe(300270);
    expect(index.resolve({ volcano_number: 999999999 })).toBeNull();
  });
});

describe("active alert cards", () => {
  const ev = (n: number, source: string, level: string, t: string): AlertEvent => ({
    volcano_number: n, source, kind: "volcano_level", label: `${source} ${level}`, level, event_time: t, detail: null, url: null, first_seen: t,
  });
  it("skips normal status, groups per volcano, newest group first", () => {
    const events = [ev(2, "JMA", "3", "2026-10-30T07:00:00+00:00"), ev(1, "PVMBG", "1", "2026-10-30T06:00:00+00:00"),
      ev(1, "PVMBG", "2", "2026-10-30T05:00:00+00:00"), ev(3, "KVERT", "GREEN", "2026-10-30T04:00:00+00:00")];
    const g = groupActiveAlerts(events, new Map([[1, "A"], [2, "B"]]));
    expect(g.count).toBe(2);
    expect(g.cards.map((c) => c.name)).toEqual(["B", "A"]);
    expect(g.cards[1].items).toHaveLength(1);
  });
});
